export const sizeName = size => ({S:'Chica',M:'Mediana',L:'Grande',U:'Ajuste por confirmar'}[size]||size);
export const sizeLabel = size => size==='U'?'Ajuste por confirmar':String(size).split('-').map(code=>`${sizeName(code)} (${code})`).join(' / ');
export const campaign = {name:'Black Friday',active:true,unitPrice:650};
export const salePrice = product => !campaign.active?product.price:product.category==='Playeras'&&product.collection==='Luxury Edition'?campaign.unitPrice:product.blackFridayPrice??product.price;
export function totals(cart) {
  const subtotal = cart.reduce((sum,line) => sum + (products.find(p=>p.id===line.id)?.price || 0)*line.qty,0);
  const promotionSubtotal = cart.reduce((sum,line)=>{const p=products.find(p=>p.id===line.id);return sum+(p&&p.collection==='Luxury Edition'?p.price*line.qty:0);},0);
  const discount = cart.reduce((sum,line)=>{const p=products.find(p=>p.id===line.id);return sum+(p?(p.price-salePrice(p))*line.qty:0);},0);
  return {subtotal,promotionSubtotal,discount,total:Math.round((subtotal-discount)*100)/100};
}
export function sanitizeCart(value) {
  if (!Array.isArray(value)) return [];
  const result=[];
  for (const line of value) {
    const product=products.find(p=>p.id===line?.id);
    if (!product || !product.sizes.includes(line.size) || !Number.isInteger(line.qty) || line.qty<1) continue;
    const existing=result.find(l=>l.id===line.id&&l.size===line.size);
    const used=result.filter(l=>l.id===line.id).reduce((n,l)=>n+l.qty,0);
    const qty=Math.min(line.qty,product.stock-used);
    if (qty>0) { if(existing) existing.qty+=qty; else result.push({id:line.id,size:line.size,qty}); }
  }
  return result;
}
